<?php

namespace App\Exports;

/**
 * One report, ready to be written to a file: the same content for PDF, Excel and CSV, so the three
 * formats never disagree. Built by ReportDocumentBuilder; written by a ReportWriter.
 *
 * Every value is final: names instead of ids, labels instead of codes. Cells are strings, or
 * numbers where a spreadsheet should be able to add them up; null is an empty cell.
 *
 *   info      the report information block, label => text (report, generated by, period, filters...)
 *   headings  the table's column headings
 *   rows      one list of cells per row, in the order of headings
 *   totals    the report's totals, label => number
 *   money     the indexes of the columns that hold amounts of money (formatted as such in PDF / Excel)
 */
final readonly class ReportDocument
{
    /**
     * @param  array<string, string>  $info
     * @param  list<string>  $headings
     * @param  list<list<string|int|float|null>>  $rows
     * @param  array<string, int|float>  $totals
     * @param  list<int>  $money
     * @param  list<string>  $moneyTotals  the labels in $totals that are amounts of money
     */
    public function __construct(
        public string $title,
        public array $info,
        public array $headings,
        public array $rows,
        public array $totals,
        public array $money = [],
        public array $moneyTotals = [],
    ) {}
}
